"Then add the third number to {N}.":"再把第三個數加到{N}上。",
"Which two numbers make {N}?":"哪兩個數合起來是{N}？",
"Make a {N} first, then add the rest.":"先湊成{N}，再加上剩下的。",
"Roll three dice and look for a pair that makes {N} or a double.":"擲三顆骰子，找出合成{N}的一對或雙倍。",
"Find the missing number":"找出缺少的數",
"A number is hiding behind Pip!":"有個數躲在Pip後面！",
"Read {N} + {Q} = {N} as \"{N} and what make {N}?\"":"把{N1} + {Q} = {N2}讀成「{N3}加多少是{N4}？」",
"Count on from {N} to {N}.":"從{N}往上數到{N}。",
"You counted on {N}, so the hiding number is {N}.":"你往後數了{N}，所以躲起來的數是{N}。",
"Count on from the first number to the total.":"從第一個數往後數到總數。",
"Find the missing part: total take away the part you know.":"找出缺少的部分：總數減去你知道的部分。",
"Hide some coins under a cup: \"There were {N}, now I see {N}.":"把一些硬幣藏在杯子下：「本來有{N}個，現在看到{N}個。",
"How many are hiding?\"":"藏起來的有幾個？」",
"What the equal sign means":"等號是什麼意思",
"The equal sign is a balance.":"等號就像天平。",
"= means both sides are the same amount.":"=表示兩邊一樣多。",
"Work out each side.":"把兩邊都算出來。",
"If both sides match, it is true.":"如果兩邊相同，就是對的。",
"What does each side make?":"每一邊各是多少？",
"Both sides of = must be the same amount.":"=的兩邊必須一樣多。",
"Use a balance or a ruler on a pencil with coins on each side to show \"the same\".":"用天平，或把尺放在鉛筆上，兩邊放硬幣，示範「一樣多」。",
"Tens and ones":"十位和個位",
"Beads come in rods of ten.":"珠子十個串成一條。",
"A rod is {N} ten.":"一條是{N}個十。",
"Loose beads are ones.":"單獨的珠子是一。",
"{N} tens and {N} ones is {N}.":"{N}個十和{N}個一是{N}。",
"Count the rods first, then the loose {T}.":"先數條，再數單獨的{T}。",
"The left digit counts tens, the right digit counts ones.":"左邊的數字代表幾個十，右邊的數字代表幾個一。",
"Bundle straws or sticks into tens with rubber bands, then count tens and ones.":"用橡皮筋把吸管或小棒十根綁成一束，再數有幾個十、幾個一。",
"Compare {N}-digit numbers":"比較{N}位數",
"Which ferry has more passengers?":"哪一艘渡船載的乘客比較多？",
"Compare the tens first.":"先比較十位。",
"If the tens are the same, compare the ones.":"如果十位一樣，就比個位。",
"> points to the smaller number: {N} > {N}.":"> 的尖端指向比較小的數：{N} > {N}。",
