"Trade {N} dimes for a dollar.":"用{N}個十元硬幣換一張百元鈔。",
"Ask: \"How much is {N} dollars and {N} dimes?\"":"問：「{N}張百元鈔和{N}個十元硬幣是多少？」",
"Read and build {N}-digit numbers":"讀和組成{N}位數",
"Pip found some {T} in the meadow.":"Pip在草地上找到一些{T}。",
"How many are there?":"一共有多少？",
"A flat square is {N} hundred.":"一片大方塊是{N}個百。",
