"Each square is {N}, each rod is {N}, each cube is {N}.":"每片大方塊是{N}，每條長條是{N}，每個小方塊是{N}。",
"Build numbers with coins: ${N} bills as hundreds, dimes as tens, pennies as ones.":"用錢組成數：{N}元鈔當百，十元硬幣當十，一元硬幣當一。",
