"Which house is that digit in?":"這個數字住在哪一位？",
"A digit in the tens house is worth that many tens.":"十位上的數字代表幾個十。",
"Write a {N}-digit number and point at one digit.":"寫一個{N}位數，指著其中一個數字。",
"Ask: \"How much is this one worth?\" Then build it with coins to check.":"問：「這個數字代表多少？」再用硬幣排出來檢查。",
"Expanded form":"展開式",
