"Add the same jump each time.":"每次都加同樣的數。",
"Count by {N}s from a {N}-digit number in the car, like {N}, {N}, {N}.":"坐車時從一個{N2}位數開始，每次數{N1}，例如{N3}、{N4}、{N5}。",
"Zero as a placeholder":"0的佔位作用",
"Some houses are empty.":"有些房子是空的。",
"Zero keeps their spot.":"0幫它們佔住位置。",
"{N} hundreds and {N} ones has no tens.":"{N}個百和{N}個一，沒有十。",
"Write a {N} in the tens place: {N}.":"在十位寫{N}：{N}。",
"Without the {N}, it would read {N}.":"少了{N}，就會讀成{N}。",
"Is any place empty?":"有沒有空著的位？",
"Zero holds a place so the other digits stay put.":"0佔住一個位，其他數字才不會跑掉。",
"Build {N} with coins: {N} dollars, no dimes, {N} pennies.":"用錢排出{N}：{N}張百元鈔、沒有十元、{N}個一元。",
