"Count all the tens, including the ones inside the hundreds.":"數所有的十，包括藏在百裡面的十。",
"Ask how many dimes make ${N}.":"問多少個十元硬幣是{N}元。",
"Count them out if needed.":"需要的話就數一數。",
"Two ferries are racing.":"兩艘渡船在比賽。",
"Which one carries more?":"哪一艘載得比較多？",
"Compare the hundreds first.":"先比較百位。",
"If the hundreds are the same, compare the tens.":"如果百位一樣，就比較十位。",
