"Start from the bigger number and count on.":"從比較大的數開始往後數。",
"Start counting on the next number.":"從下一個數開始數。",
"Play a quick \"make {N}\" game with fingers or coins.":"用手指或硬幣快速玩「湊{N}」。",
"Make-ten strategy":"湊十法",
"Make a ten to add faster!":"湊成十，加得更快！",
"{N} + {N}: give {N} from the {N} to the {N} to make {N}.":"{N1} + {N2}：從{N4}拿{N3}給{N5}，湊成{N6}。",
"How many more does the first number need to make {N}?":"第一個數還差多少才是{N}？",
"Fill the ten-frame first, then add what is left.":"先把十格框填滿，再加剩下的。",
"Use an egg carton cut to {N} cups.":"用一個剪成{N}格的蛋盒。",
"Fill it first, then count what is left.":"先把它填滿，再數剩下的。",
"Fact families":"算式家族",
"Adding and subtracting are a family.":"加法和減法是一家人。",
"{N} + {N} = {N}, so {N} − {N} = {N} and {N} − {N} = {N}.":"{N} + {N} = {N}，所以{N} − {N} = {N}，{N} − {N} = {N}。",
"If you know one fact, you know the family.":"知道一個算式，就知道整個家族。",
"What adding fact uses these numbers?":"哪一個加法算式用到這些數？",
"Taking away undoes adding.":"減法可以把加法還原。",
"Write one fact like {N} + {N} = {N} and ask your child for the other three in the family.":"寫一個算式，例如{N} + {N} = {N}，請孩子寫出家族裡另外三個。",
"Add {N}-digit numbers, no regrouping":"{N}位數加法（不進位）",
"The ferry carries two groups of {T} across the river.":"渡船載著兩群{T}過河。",
"Add the ones to the ones.":"個位加個位。",
"Add the tens to the tens.":"十位加十位。",
"Put them together.":"把它們合起來。",
"Start with the ones.":"從個位開始。",
"Ones add with ones, tens add with tens.":"個位和個位加，十位和十位加。",
"Add two ages or two prices under ${N} by adding dimes to dimes and pennies to pennies.":"把兩個年齡或兩個不到{N}元的價錢相加：十元硬幣和十元硬幣加，一元硬幣和一元硬幣加。",
"Add {N}-digit numbers by making a ten":"{N}位數加法（湊十進位）",
"Too many ones for one dock!":"一個碼頭放不下這麼多個一！",
"Ten ones can ride together as one ten.":"十個一可以合成一個十一起走。",
"Add the ones.":"把個位加起來。",
"If you get {N} or more, make a ten.":"如果是{N}以上，就湊成一個十。",
"Move the new ten to the tens place.":"把新的十移到十位。",
"Add the tens, including the new one.":"把十位加起來，包括新的那個十。",
"Look at the ones.":"看個位。",
"Is it more than {N}?":"有沒有超過{N}？",
"Ten ones make one ten.":"十個一是一個十。",
"Carry it to the tens.":"把它進位到十位。",
"Use {N} pennies and trade them for a dime whenever you have ten.":"用{N}個一元硬幣，每湊滿十個就換成一個十元。",
"Try {N}¢ + {N}¢.":"試試{N}元 + {N}元。",
"Subtract {N}-digit numbers, no regrouping":"{N}位數減法（不退位）",
"Some beads hop off the ferry.":"有些珠子跳下渡船。",
"How many stay?":"還有多少留在船上？",
"Take the ones from the ones.":"個位減個位。",
"Take the tens from the tens.":"十位減十位。",
"Ones from ones, tens from tens.":"個位減個位，十位減十位。",
"Count dimes and pennies, then take some away and count what is left.":"數一數十元和一元硬幣，拿走一些，再數剩下多少。",
"Subtract {N}-digit numbers by breaking a ten":"{N}位數減法（退位）",
"Not enough ones to take away?":"個位不夠減嗎？",
"Break a ten into ten ones.":"把一個十拆成十個一。",
"Can you take the bottom ones from the top ones?":"上面的個位能減去下面的個位嗎？",
"What to write on paper":"要寫在紙上的內容",
"What went wrong":"哪裡出錯了",
"Why did that work":"為什麼行得通",
