"Children use it under that parent's account on this device.":"孩子在這台裝置上使用該家長的帳戶。",
"A skill counts as mastered after at least {N} answers without big hints, {N} of the last {N} right, in two kinds of question, and a mastery estimate of {N}%.":"一項技能要算熟練，需要至少{N1}題沒用大提示、最近{N3}題答對{N2}題、做過兩種題型，而且熟練度估計達到{N4}%。",
"It is certified only after it is still right {N} and {N} days later, and checked again at {N} days.":"要在{N}天和{N}天後仍然答對才算通過，並在第{N}天再檢查一次。",
