"Here is where it lives.":"它在這裡。",
"You were {N}% away.":"你差了{N}%。",
"Write that down.":"把它寫下來。",
"{N} × {N} = {N}, so the smallest is {N}.":"{N} × {N} = {N}，所以最小的是{N}。",
"So {N} ÷ {N} = {N}.":"所以{N} ÷ {N} = {N}。",
"{N} is one more than {N}, so {N} + {N} = {N}.":"{N}比{N}多一，所以{N} + {N} = {N}。",
"{N} layers: {N} × {N} = {N}.":"{N}層：{N} × {N} = {N}。",
"{N} tenths = {N}.":"{N}個十分之一 = {N}。",
"{N} × {N} = {N}, so {Q} = {N}.":"{N} × {N} = {N}，所以{Q} = {N}。",
"{N} × {N} tens = {N} tens = {N}.":"{N} × {N}個十 = {N}個十 = {N}。",
"Multiply the tops: {N} × {N} = {N}.":"分子相乘：{N} × {N} = {N}。",
"Ones: {N} + {N} + {N} = {N}.":"個位：{N} + {N} + {N} = {N}。",
"Only the pieces are counted: {N} + {N} = {N}, and the bottom is still {N}.":"只數塊數：{N} + {N} = {N}，分母還是{N}。",
"So {N} − {N} = {N}.":"所以{N} − {N} = {N}。",
"Take away one group of {N}: {N} − {N} = {N}.":"減掉一組{N}：{N} − {N} = {N}。",
"Tens: {N} + {N} + {N} = {N} tens.":"十位：{N} + {N} + {N} = {N}個十。",
"There is {N} decimal place in all, so {N} × {N} = {N}.":"一共有{N}位小數，所以{N} × {N} = {N}。",
"hundreds: {N} + {N} + {N} = {N}.":"百位：{N} + {N} + {N} = {N}。",
"hundreds: {N} − {N} = {N}.":"百位：{N} − {N} = {N}。",
"ones: {N} − {N} = {N}.":"個位：{N} − {N} = {N}。",
