"Hi, I'm Pip!":"嗨，我是Pip！",
"I'm a helper made by the Tenbright team using a computer, and my voice is made by a computer too.":"我是Tenbright團隊用電腦做出來的小幫手，我的聲音也是電腦做的。",
"I collect light-beads.":"我在收集光珠。",
"Ten beads make a lantern.":"十顆光珠可以做成一盞燈籠。",
"Will you help me light the Kingdom?":"你願意幫我點亮王國嗎？",
"Hint":"提示",
"Try again.":"再試一次。",
"Homeschool or not sure":"在家自學或不確定",
"How long we keep it":"我們保存多久",
"How we use it":"我們如何使用",
"How we'll know":"我們怎麼知道",
"Hundreds are the same, so look at the ones.":"百位一樣，所以看個位。",
"I agree that Tenbright may keep my child's learning record on this device to choose their next activity and show me their progress.":"我同意Tenbright把孩子的學習紀錄保存在這台裝置上，用來安排下一個活動並讓我查看進度。",
"I am this child's parent or legal guardian.":"我是這個孩子的家長或法定監護人。",
"I found {N} lanterns you can already light.":"我找到{N}盞你已經可以點亮的燈籠。",
"Now the map knows where to start.":"現在地圖知道要從哪裡開始了。",
"I worked this out, but I made a mistake.":"我算出來了，可是我犯了一個錯。",
"Can you find it?":"你找得到嗎？",
"I wrote it":"我寫好了",
"If we change what we collect or how we use it, we will ask for your consent again before the change applies to your child.":"如果我們改變收集的內容或使用方式，會在套用到孩子之前再次徵求你的同意。",
"If you switch on voice answers on the grown-ups page, your child can tap the Talk button and say a number or a short command such as \"next\".":"如果你在家長頁面開啟語音作答，孩子可以按「說話」按鈕，說出一個數字或像「下一個」這樣的簡短指令。",
"Speech is turned into text by your browser on this device; Tenbright uses it only if the browser can promise this happens on the device.":"語音會由這台裝置上的瀏覽器轉成文字；只有在瀏覽器能保證在裝置上完成時，Tenbright才會使用。",
"The words are used once to read the answer and are then discarded.":"這些字只用一次來讀取答案，之後就丟棄。",
"No audio and no transcript is recorded, kept or sent to us or anyone else.":"不會錄下、保存或傳送任何聲音或文字紀錄給我們或任何人。",
"The microphone is used only after a tap on Talk, for one short answer.":"只有按下「說話」後才會使用麥克風，而且只聽一個簡短的答案。",
"Pip never asks your child to say their name or anything about themselves.":"Pip絕不會要孩子說出名字或任何關於自己的事。",
"You can switch voice answers off at any time.":"你可以隨時關閉語音作答。",
"In the full product this step will use an FTC-recognized method of verifiable parental consent.":"在正式版中，這個步驟會使用美國聯邦貿易委員會（FTC）認可的可驗證家長同意方式。",
"This preview records your agreement on this device only.":"這個預覽版只在這台裝置上記錄你的同意。",
"In this preview, everything stays in this browser on this device.":"在這個預覽版中，所有資料都留在這台裝置的瀏覽器裡。",
"Nothing is sent to us or to anyone else.":"不會傳送任何資料給我們或任何人。",
"The app loads no outside fonts, analytics, ads or trackers.":"這個應用程式不載入外部字型、分析工具、廣告或追蹤器。",
"Pip's voice is recorded audio made with an AI voice model and included in the app; if a sentence has no recording, a voice built into your device reads it.":"英文版的Pip聲音是用AI語音模型錄製並內建在應用程式中的音檔；其他語言，或沒有錄音的句子，會由你裝置內建的語音朗讀。",
"Speech recognition, if you turn it on, runs only on your device.":"語音辨識如果開啟，只會在你的裝置上執行。",
"Just looking?":"只是看看嗎？",
"Keeps your child out of settings and reports.":"讓孩子無法進入設定和報告。",
