"With a parent's consent, the app keeps a child's nickname and birth year, and a record of their answers: which skill, whether it was right, which hints they used, which strategy they chose and how long they took, plus how close their number-line warm-up estimates were.":"經家長同意後，應用程式會保存孩子的暱稱和出生年份，以及作答紀錄：哪項技能、是否答對、用了哪些提示、選了哪種策略、花了多久，還有數線暖身時估計得多準。",
"Children type numbers and tap choices.":"孩子輸入數字並點選選項。",
"The app has no chat, camera, photos, location or contacts, and asks for no real name.":"應用程式沒有聊天、相機、照片、位置或聯絡人功能，也不要求真實姓名。",
"Work it with Pip":"和Pip一起算",
"Working on":"正在學",
"Write it on your paper":"把它寫在紙上",
"Write it on your paper, then tap":"把它寫在紙上，然後按",
"Yes!":"對！",
"Write {N} on your paper.":"在紙上寫{N}。",
"You can review everything stored about your child from the grown-ups page (\"See everything stored\"), delete one child's data, or erase everything at any time.":"你可以隨時在家長頁面（「查看所有儲存的資料」）查看孩子的所有資料、刪除一個孩子的資料，或全部清除。",
"Erasing everything withdraws your consent.":"全部清除即表示撤回同意。",
"We will not require more information than the app needs as a condition of your child playing.":"我們不會要求超過應用程式所需的資料，作為孩子使用的條件。",
"You set things up and give consent.":"由你設定並給予同意。",
"Your child never sees a form, a price or an ad.":"孩子永遠不會看到表單、價格或廣告。",
"Your child's nickname and birth year, their answers, timings, hints used and which strategies they chose.":"孩子的暱稱和出生年份、作答、時間、用過的提示和選擇的策略。",
"That is all.":"就這些。",
"It stays on this device.":"資料留在這台裝置上。",
"Your first name (optional)":"你的名字（選填）",
"Your rights as a parent":"家長的權利",
