"and the top is {N}":"，分子是{N}",
"and the top is {N}.":"，分子是{N}。",
"away.":"的差距。",
"Lower is sharper.":"越低越準。",
"count to {N}; add within {N}.":"數到{N}；{N}以內的加法。",
"for Parents":"家長版",
"go?":"在哪裡？",
"Tap the line.":"點數線。",
"lanterns lit":"盞燈籠已點亮",
"learning":"學習中",
"of {N} = {N}":"（{N}的）= {N}",
"of {N} lanterns lit":"/ {N}盞燈籠已點亮",
