"sessions":"次練習",
"skills mastered":"項技能已熟練",
"tens: {N} + {N} + {N} = {Q} make a ten":"十位：{N} + {N} + {N} = {Q}，湊成十",
"times and fixed it":"次並改正了",
"times.":"次。",
