"Only two sides":"只算了兩條邊",
"Area and perimeter mixed":"面積和周長弄混了",
"Right angle as 100":"把直角當成100度",
"Up before across":"先往上再往右",
"Reads the number at the end of an object on a ruler instead of counting the units from where it starts.":"讀出物體在尺上終點的數字，而不是從起點開始數有幾個單位。",
"Adds only the two given sides of a rectangle instead of all four for the perimeter.":"算周長時只加了長方形給出的兩條邊，而不是四條邊。",
"Finds the distance around when the question asks for the squares inside, or the other way around.":"題目問裡面有幾個正方形時卻算了周長，或反過來。",
"Treats a right angle as 100 degrees instead of 90.":"把直角當成100度，而不是90度。",
"Reads how far up a point is before how far across on a grid.":"在方格上先讀往上多少，再讀往右多少。",
"It does not start at {N}.":"它不是從{N}開始的。",
"Count the units from the start to the end.":"從起點數到終點有幾個單位。",
"The perimeter goes all the way around.":"周長是繞一整圈。",
