"Area counts the squares inside.":"面積是數裡面的正方形。",
"Perimeter is the distance around the edge.":"周長是繞邊緣一圈的長度。",
"A right angle is {N} degrees, not {N}.":"直角是{N}度，不是{N}度。",
"Go across first, then up.":"先往右，再往上。",
