"Pip added only two sides of the rectangle.":"Pip只加了長方形的兩條邊。",
"Pip mixed up area and perimeter.":"Pip把面積和周長弄混了。",
"Pip used {N} degrees for a right angle.":"Pip把直角當成{N}度。",
"Pip went up first, then across.":"Pip先往上，再往右。",
"It starts at {N} and ends at {N}.":"它從{N}開始，到{N}結束。",
"It starts at {N}, not at {N}.":"它從{N}開始，不是從{N}開始。",
"Count the units from {N} to {N}.":"數從{N}到{N}有幾個單位。",
"The object starts at {N} and ends at {N}.":"物體從{N}開始，到{N}結束。",
"Two ribbons.":"兩條緞帶。",
"The red ribbon is {N} long.":"紅緞帶長{N}。",
"The blue ribbon is {N} long.":"藍緞帶長{N}。",
"How much longer is the red ribbon?":"紅緞帶長多少？",
"How much longer means find the difference.":"「長多少」就是要找差。",
"How much longer means subtract.":"「長多少」就是要用減法。",
"Line up one end with {N}.":"把一端對齊{N}。",
"Read the number at the other end.":"讀出另一端的數字。",
"If it does not start at {N}, count the units from start to end.":"如果不是從{N}開始，就從起點數到終點。",
"Where does it start?":"它從哪裡開始？",
"Count the units, not the last number.":"數單位，不是看最後一個數字。",
"Measure a spoon and a shoe with a ruler.":"用尺量一量湯匙和鞋子。",
"Welcome to the Measuring Workshop!":"歡迎來到測量工坊！",
"Which is longer, and by how much?":"哪一個比較長？長多少？",
"Measure both in the same unit.":"用同一種單位量兩個。",
"Take the shorter length from the longer one.":"用較長的長度減去較短的長度。",
"Is it a difference or a total?":"是求差還是求總數？",
"Measure two toys and say how much longer one is.":"量兩個玩具，說出一個比另一個長多少。",
"A rectangle.":"一個長方形。",
"The long side is {N}.":"長邊是{N}。",
"The short side is {N}.":"短邊是{N}。",
"The short side is not known.":"短邊的長度不知道。",
"How wide is it?":"寬是多少？",
"Opposite sides are the same length.":"相對的邊一樣長。",
"Add all {N} sides: {N} + {N} + {N} + {N} = {N}":"把{N}條邊加起來：{N} + {N} + {N} + {N} = {N}",
"Walk all the way around.":"繞一整圈走。",
"Perimeter is the distance around a shape.":"周長是圖形一圈的長度。",
"Add the length of every side.":"把每一條邊的長度加起來。",
"A rectangle has two pairs of sides that are the same length.":"長方形有兩組一樣長的邊。",
"How many sides does it have?":"它有幾條邊？",
"Add every side, all the way around.":"繞一圈，把每條邊都加起來。",
"Walk around a rug or a table and count your steps.":"繞著地毯或桌子走一圈，數一數走了幾步。",
"How many squares cover the rectangle?":"有幾個正方形鋪滿這個長方形？",
"A rectangle covered by squares: {N} rows, {N} squares in each row.":"一個鋪滿正方形的長方形：{N}排，每排{N}個。",
"There are {N} rows with {N} squares in each row.":"有{N}排，每排{N}個正方形。",
"Area is the length times the width.":"面積是長乘以寬。",
"How many squares cover it?":"要幾個正方形才能鋪滿？",
"Area is how many squares cover a shape.":"面積是鋪滿圖形需要幾個正方形。",
"Count the squares in one row.":"數一排有幾個正方形。",
"Multiply by the number of rows.":"再乘以排數。",
"How many squares in each row?":"每排有幾個正方形？",
"Rows times the squares in each row.":"排數乘以每排的正方形數。",
"Cover a book with sticky notes and count them.":"用便利貼鋪滿一本書，再數一數。",
"What is this shape called?":"這個圖形叫什麼？",
"A closed shape with {N} straight sides.":"一個有{N}條直邊的封閉圖形。",
"Count the straight sides.":"數一數有幾條直邊。",
"Count the sides, then name the shape.":"先數邊，再說出圖形名稱。",
"Welcome to the Shape Garden!":"歡迎來到圖形花園！",
"Find shapes at home: a triangle, a quadrilateral and a hexagon.":"在家裡找圖形：三角形、四邊形和六邊形。",
"A right angle is split into two angles.":"一個直角被分成兩個角。",
"A straight angle is split into two angles.":"一個平角被分成兩個角。",
"One angle is {N} degrees.":"其中一個角是{N}度。",
