"A right angle is {N} degrees.":"直角是{N}度。",
"A straight angle is {N} degrees.":"平角是{N}度。",
"A right angle split into two parts.":"一個分成兩部分的直角。",
"A straight angle split into two parts.":"一個分成兩部分的平角。",
"One part is {N} degrees.":"其中一部分是{N}度。",
"The other part is not known.":"另一部分不知道。",
"Angles fit together.":"角可以拼在一起。",
"The two parts add up to the whole angle.":"兩部分合起來是整個角。",
"Take the part you know from the whole.":"用整個角減去已知的部分。",
"Is it a right angle or a straight angle?":"是直角還是平角？",
"The whole angle take away the part you know.":"整個角減去已知的部分。",
"Find right angles at home, like the corner of a book or a door.":"在家裡找直角，例如書角或門角。",
"How far across from {N} is the star?":"星星從{N}往右走了多遠？",
"How far up from {N} is the star?":"星星從{N}往上走了多遠？",
"A grid numbered {N} to {N} across the bottom and up the side, with a star on it.":"一個下面和旁邊標了{N}到{N}的方格，上面有一顆星星。",
"Go across to {N}.":"往右走到{N}。",
"Then go up to {N}.":"再往上走到{N}。",
"The star is {N} across and {N} up.":"星星在往右{N}、往上{N}的地方。",
