"What does one cost?":"一個要多少錢？",
"A pack price is for all the items in it.":"一包的價錢是包裡所有東西的價錢。",
"Divide the pack price by how many items.":"用一包的價錢除以數量。",
"That gives the price for one, called the unit price.":"這樣就得到一個的價錢，叫做單價。",
"Compare unit prices to find the better buy.":"比較單價，找出比較划算的買法。",
"How many items are in the pack?":"一包裡有幾個？",
"The pack price divided by how many.":"一包的價錢除以數量。",
