"Each point shows the price in one week.":"每一個點表示一週的價錢。",
"Find the week along the bottom and the price up the side.":"週數在下面，價錢在旁邊。",
"Take one price from the other to find the change.":"用一個價錢減去另一個，就是變化。",
"Going up before does not mean it will go up again.":"以前漲過，不代表還會再漲。",
"Which two weeks does the question ask about?":"題目問的是哪兩週？",
"Find both prices, then take the smaller from the bigger.":"找出兩個價錢，再用大的減小的。",
