"Shops try different prices: a higher price can mean fewer sales.":"商店會試不同的價錢：價錢越高，可能賣得越少。",
"When costs are bigger than sales, a business has a loss that day.":"成本比銷售額多的時候，那天生意就虧損了。",
"Shoppers round prices to check quickly whether a list fits their money.":"購物的人會把價錢四捨五入，快速確認清單買得起。",
"Prices use a decimal point: dollars on the left, cents on the right.":"價錢用小數點：左邊是元，右邊是分。",
"Shelf labels often show the price for one, so shoppers can compare packs.":"貨架標籤常會標出單價，方便比較不同包裝。",
"Friends who share a meal often divide the bill so each pays the same.":"朋友一起吃飯，常會平分帳單，每人付一樣多。",
"Some companies pay part of their profit to the people who own shares.":"有些公司會把一部分利潤發給擁有股份的人。",
"Businesses compare the cost of one item in small and big packs.":"生意人會比較小包和大包裡一個的成本。",
"Money saved earlier has more years to grow.":"越早存的錢，有越多年可以成長。",
"The price of a share goes up and down; going up last week does not mean it will next week.":"股價會上上下下；上週漲了，不代表下週也會漲。",
"Ask: if a toy cost twice as much, would as many people buy it?":"問問看：如果玩具貴一倍，還會有一樣多的人買嗎？",
"Talk about a time plans changed because of the weather, and what it cost.":"聊聊有一次因為天氣改變計畫，花了多少錢。",
"Before checkout, round each item on a short list and estimate the total together.":"結帳前，把短清單上每樣東西四捨五入，一起估算總價。",
"At the store, find two pack sizes of the same thing and work out the price for one.":"在商店找同一樣東西的兩種包裝，算出一個的價錢。",
"Share a pretend bill for a family meal and work out each person’s part.":"分一張假裝的家庭聚餐帳單，算出每個人要付多少。",
"Ask: if a company makes more profit, what happens to each owner’s part?":"問問看：如果公司賺得更多，每位股東的那一份會怎樣？",
"And if it makes less?":"如果賺得少呢？",
"Compare the price for one in a small and a big pack of something you buy often.":"比較常買東西的小包和大包的單價。",
